264	/// getX86CpuIDAndInfo - Execute the specified cpuid and return the 4 values in
265	/// the specified arguments.  If we can't run cpuid on the host, return true.
266	static bool getX86CpuIDAndInfo(unsigned value, unsigned *rEAX, unsigned *rEBX,
267	                               unsigned *rECX, unsigned *rEDX) {
268	#if (defined(__GNUC__) || defined(__clang__)) && !defined(_MSC_VER)
269	  return !__get_cpuid(value, rEAX, rEBX, rECX, rEDX);
270	#elif defined(_MSC_VER)
271	  // The MSVC intrinsic is portable across x86 and x64.
272	  int registers[4];
273	  __cpuid(registers, value);
274	  *rEAX = registers[0];
275	  *rEBX = registers[1];
276	  *rECX = registers[2];
277	  *rEDX = registers[3];
278	  return false;
279	#else
280	  return true;
281	#endif
282	}
