284	/// getX86CpuIDAndInfoEx - Execute the specified cpuid with subleaf and return
285	/// the 4 values in the specified arguments.  If we can't run cpuid on the host,
286	/// return true.
287	static bool getX86CpuIDAndInfoEx(unsigned value, unsigned subleaf,
288	                                 unsigned *rEAX, unsigned *rEBX, unsigned *rECX,
289	                                 unsigned *rEDX) {
290	  // TODO(boomanaiden154): When the minimum toolchain versions for gcc and clang
291	  // are such that __cpuidex is defined within cpuid.h for both, we can remove
292	  // the __get_cpuid_count function and share the MSVC implementation between
293	  // all three.
294	#if (defined(__GNUC__) || defined(__clang__)) && !defined(_MSC_VER)
295	  return !__get_cpuid_count(value, subleaf, rEAX, rEBX, rECX, rEDX);
296	#elif defined(_MSC_VER)
297	  int registers[4];
298	  __cpuidex(registers, value, subleaf);
299	  *rEAX = registers[0];
300	  *rEBX = registers[1];
301	  *rECX = registers[2];
302	  *rEDX = registers[3];
303	  return false;
304	#else
305	  return true;
306	#endif
307	}
