309	// Read control register 0 (XCR0). Used to detect features such as AVX.
310	static bool getX86XCR0(unsigned *rEAX, unsigned *rEDX) {
311	  // TODO(boomanaiden154): When the minimum toolchain versions for gcc and clang
312	  // are such that _xgetbv is supported by both, we can unify the implementation
313	  // with MSVC and remove all inline assembly.
314	#if defined(__GNUC__) || defined(__clang__)
315	  // Check xgetbv; this uses a .byte sequence instead of the instruction
316	  // directly because older assemblers do not include support for xgetbv and
317	  // there is no easy way to conditionally compile based on the assembler used.
318	  __asm__(".byte 0x0f, 0x01, 0xd0" : "=a"(*rEAX), "=d"(*rEDX) : "c"(0));
319	  return false;
320	#elif defined(_MSC_FULL_VER) && defined(_XCR_XFEATURE_ENABLED_MASK)
321	  unsigned long long Result = _xgetbv(_XCR_XFEATURE_ENABLED_MASK);
322	  *rEAX = Result;
323	  *rEDX = Result >> 32;
324	  return false;
325	#else
326	  return true;
327	#endif
328	}
