330	static void detectX86FamilyModel(unsigned EAX, unsigned *Family,
331	                                 unsigned *Model) {
332	  *Family = (EAX >> 8) & 0xf; // Bits 8 - 11
333	  *Model = (EAX >> 4) & 0xf;  // Bits 4 - 7
334	  if (*Family == 6 || *Family == 0xf) {
335	    if (*Family == 0xf)
336	      // Examine extended family ID if family ID is F.
337	      *Family += (EAX >> 20) & 0xff; // Bits 20 - 27
338	    // Examine extended model ID if family ID is 6 or F.
339	    *Model += ((EAX >> 16) & 0xf) << 4; // Bits 16 - 19
340	  }
341	}
