1133	  if (HasLeaf7Subleaf1 && ((EDX >> 21) & 1) && HasAPXSave)
1134	    setFeature(FEATURE_APXF);
1135	
1136	  unsigned MaxLevel = 0;
1137	  getX86CpuIDAndInfo(0, &MaxLevel, &EBX, &ECX, &EDX);
1138	  bool HasLeafD = MaxLevel >= 0xd &&
1139	                  !getX86CpuIDAndInfoEx(0xd, 0x1, &EAX, &EBX, &ECX, &EDX);
1140	  if (HasLeafD && ((EAX >> 0) & 1) && HasAVXSave)
1141	    setFeature(FEATURE_XSAVEOPT);
1142	  if (HasLeafD && ((EAX >> 1) & 1) && HasAVXSave)
1143	    setFeature(FEATURE_XSAVEC);
1144	  if (HasLeafD && ((EAX >> 3) & 1) && HasAVXSave)
1145	    setFeature(FEATURE_XSAVES);
1146	
1147	  bool HasLeaf1E = MaxLevel >= 0x1e &&
1148	                   !getX86CpuIDAndInfoEx(0x1e, 0x1, &EAX, &EBX, &ECX, &EDX);
1149	  if (HasLeaf1E && (EAX & 0x10))
1150	    setFeature(FEATURE_AMX_FP8);
1151	  if (HasLeaf1E && (EAX & 0x80))
1152	    setFeature(FEATURE_AMX_AVX512);
1153	  if (HasLeaf1E && (EAX & 0x100))
1154	    setFeature(FEATURE_AMX_MOVRS);
1155	
1156	  bool HasLeaf24 = MaxLevel >= 0x24 &&
1157	                   !getX86CpuIDAndInfoEx(0x24, 0x0, &EAX, &EBX, &ECX, &EDX);
1158	  if (HasLeaf7Subleaf1 && ((EDX >> 19) & 1) && HasLeaf24) {
1159	    int AVX10Ver = EBX & 0xff;
1160	    if (AVX10Ver >= 1)
1161	      setFeature(FEATURE_AVX10_1);
1162	    if (AVX10Ver >= 2)
1163	      setFeature(FEATURE_AVX10_2);
1164	  }
1165	
1166	  unsigned MaxExtLevel = 0;
1167	  getX86CpuIDAndInfo(0x80000000, &MaxExtLevel, &EBX, &ECX, &EDX);
1168	
1169	  bool HasExtLeaf1 = MaxExtLevel >= 0x80000001 &&
1170	                     !getX86CpuIDAndInfo(0x80000001, &EAX, &EBX, &ECX, &EDX);
1171	  if (HasExtLeaf1) {
1172	    if (ECX & 1)
1173	      setFeature(FEATURE_LAHF_LM);
1174	    if ((ECX >> 5) & 1)
1175	      setFeature(FEATURE_LZCNT);
1176	    if (((ECX >> 6) & 1))
1177	      setFeature(FEATURE_SSE4_A);
1178	    if (((ECX >> 8) & 1))
1179	      setFeature(FEATURE_PRFCHW);
1180	    if (((ECX >> 11) & 1))
1181	      setFeature(FEATURE_XOP);
1182	    if (((ECX >> 15) & 1))
1183	      setFeature(FEATURE_LWP);
1184	    if (((ECX >> 16) & 1))
1185	      setFeature(FEATURE_FMA4);
1186	    if (((ECX >> 21) & 1))
1187	      setFeature(FEATURE_TBM);
1188	    if (((ECX >> 29) & 1))
1189	      setFeature(FEATURE_MWAITX);
1190	
1191	    if (((EDX >> 29) & 1))
1192	      setFeature(FEATURE_LM);
1193	  }
1194	
1195	  bool HasExtLeaf8 = MaxExtLevel >= 0x80000008 &&
1196	                     !getX86CpuIDAndInfo(0x80000008, &EAX, &EBX, &ECX, &EDX);
1197	  if (HasExtLeaf8 && ((EBX >> 0) & 1))
1198	    setFeature(FEATURE_CLZERO);
1199	  if (HasExtLeaf8 && ((EBX >> 9) & 1))
1200	    setFeature(FEATURE_WBNOINVD);
1201	
1202	  bool HasExtLeaf21 = MaxExtLevel >= 0x80000021 &&
1203	                      !getX86CpuIDAndInfo(0x80000021, &EAX, &EBX, &ECX, &EDX);
1204	  // AMD cpuid bit for prefetchi is different from Intel
1205	  if (HasExtLeaf21 && ((EAX >> 20) & 1))
1206	    setFeature(FEATURE_PREFETCHI);
1207	  if (HasExtLeaf21 && ((EAX >> 23) & 1) && HasAVX512Save)
1208	    setFeature(FEATURE_AVX512BMM);
1209	
1210	  bool HasLeaf14 = MaxLevel >= 0x14 &&
1211	                   !getX86CpuIDAndInfoEx(0x14, 0x0, &EAX, &EBX, &ECX, &EDX);
1212	  if (HasLeaf14 && ((EBX >> 4) & 1))
1213	    setFeature(FEATURE_PTWRITE);
1214	
1215	  bool HasLeaf19 =
1216	      MaxLevel >= 0x19 && !getX86CpuIDAndInfo(0x19, &EAX, &EBX, &ECX, &EDX);
1217	  if (HasLeaf7 && HasLeaf19 && ((EBX >> 2) & 1))
1218	    setFeature(FEATURE_WIDEKL);
1219	
1220	  if (hasFeature(FEATURE_LM) && hasFeature(FEATURE_SSE2)) {
1221	    setFeature(FEATURE_X86_64_BASELINE);
1222	    if (hasFeature(FEATURE_CMPXCHG16B) && hasFeature(FEATURE_POPCNT) &&
1223	        hasFeature(FEATURE_LAHF_LM) && hasFeature(FEATURE_SSE4_2)) {
1224	      setFeature(FEATURE_X86_64_V2);
1225	      if (hasFeature(FEATURE_AVX2) && hasFeature(FEATURE_BMI) &&
1226	          hasFeature(FEATURE_BMI2) && hasFeature(FEATURE_F16C) &&
1227	          hasFeature(FEATURE_FMA) && hasFeature(FEATURE_LZCNT) &&
1228	          hasFeature(FEATURE_MOVBE)) {
1229	        setFeature(FEATURE_X86_64_V3);
1230	        if (hasFeature(FEATURE_AVX512BW) && hasFeature(FEATURE_AVX512CD) &&
1231	            hasFeature(FEATURE_AVX512DQ) && hasFeature(FEATURE_AVX512VL))
1232	          setFeature(FEATURE_X86_64_V4);
1233	      }
1234	    }
1235	  }
1236	
