1244	int __cpu_indicator_init(void) CONSTRUCTOR_ATTRIBUTE;
1245	
1246	#ifndef _WIN32
1247	__attribute__((visibility("hidden")))
1248	#endif
1249	unsigned __cpu_features2[(CPU_FEATURE_MAX - 1) / 32];
1250	
1251	// A constructor function that is sets __cpu_model and __cpu_features2 with
1252	// the right values.  This needs to run only once.  This constructor is
1253	// given the highest priority and it should run before constructors without
1254	// the priority set.  However, it still runs after ifunc initializers and
1255	// needs to be called explicitly there.
1256	
1257	int CONSTRUCTOR_ATTRIBUTE __cpu_indicator_init(void) {
1258	  unsigned EAX = 0, EBX = 0, ECX = 0, EDX = 0;
1259	  unsigned MaxLeaf = 5;
1260	  unsigned Vendor;
1261	  unsigned Model, Family;
1262	  unsigned Features[(CPU_FEATURE_MAX + 31) / 32] = {0};
1263	  _Static_assert(sizeof(Features) / sizeof(Features[0]) == 4, "");
1264	  _Static_assert(sizeof(__cpu_features2) / sizeof(__cpu_features2[0]) == 3, "");
1265	
1266	  // This function needs to run just once.
1267	  if (__cpu_model.__cpu_vendor)
1268	    return 0;
1269	
1270	  if (getX86CpuIDAndInfo(0, &MaxLeaf, &Vendor, &ECX, &EDX) || MaxLeaf < 1) {
1271	    __cpu_model.__cpu_vendor = VENDOR_OTHER;
1272	    return -1;
1273	  }
1274	
1275	  getX86CpuIDAndInfo(1, &EAX, &EBX, &ECX, &EDX);
1276	  detectX86FamilyModel(EAX, &Family, &Model);
1277	
1278	  // Find available features.
1279	  getAvailableFeatures(ECX, EDX, MaxLeaf, &Features[0]);
1280	
1281	  __cpu_model.__cpu_features[0] = Features[0];
1282	  __cpu_features2[0] = Features[1];
1283	  __cpu_features2[1] = Features[2];
1284	  __cpu_features2[2] = Features[3];
1285	
1286	  if (Vendor == SIG_INTEL) {
1287	    // Get CPU type.
1288	    getIntelProcessorTypeAndSubtype(Family, Model, &Features[0], &__cpu_model);
1289	    __cpu_model.__cpu_vendor = VENDOR_INTEL;
1290	  } else if (Vendor == SIG_AMD) {
1291	    // Get CPU type.
1292	    getAMDProcessorTypeAndSubtype(Family, Model, &Features[0], &__cpu_model);
1293	    __cpu_model.__cpu_vendor = VENDOR_AMD;
1294	  } else if (Vendor == SIG_HYGON) {
1295	    getHygonProcessorTypeAndSubtype(Family, Model, &Features[0], &__cpu_model);
1296	    __cpu_model.__cpu_vendor = VENDOR_HYGON;
1297	  } else
1298	    __cpu_model.__cpu_vendor = VENDOR_OTHER;
1299	
1300	#if __STDC_HOSTED__
1301	  assert(__cpu_model.__cpu_vendor < VENDOR_MAX);
1302	  assert(__cpu_model.__cpu_type < CPU_TYPE_MAX);
1303	  assert(__cpu_model.__cpu_subtype < CPU_SUBTYPE_MAX);
1304	#endif // __STDC_HOSTED__
1305	
1306	  return 0;
1307	}
